#include <stdlib.h>

struct Matrix {
    int rows, cols;
    int **data;
};

struct Matrix *matrix_create(int rows, int cols) {
    return NULL;
}

void matrix_destroy(struct Matrix *m) {
}

int main(void) {
    int rows, cols;
    scanf("%d %d", &rows, &cols);
    struct Matrix *m = matrix_create(rows, cols);
    if (m == NULL) {
        return 1;
    }
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            scanf("%d", &m->data[r][c]);
        }
    }
    for (int r = 0; r < rows; r++) {
        long long sum = 0;
        for (int c = 0; c < cols; c++) {
            sum += m->data[r][c];
        }
        printf(r + 1 < rows ? "%lld " : "%lld\n", sum);
    }
    for (int c = 0; c < cols; c++) {
        long long sum = 0;
        for (int r = 0; r < rows; r++) {
            sum += m->data[r][c];
        }
        printf(c + 1 < cols ? "%lld " : "%lld\n", sum);
    }
    matrix_destroy(m);
    matrix_destroy(NULL);
    return 0;
}

exercise.referenceSolution:
#include <stdio.h>
#include <stdlib.h>

struct Matrix {
    int rows, cols;
    int **data;
};

void matrix_destroy(struct Matrix *m) {
    if (m == NULL) {
        return;
    }
    if (m->data != NULL) {
        for (int r = 0; r < m->rows; r++) {
            free(m->data[r]);
        }
    }
    free(m->data);
    free(m);
}

struct Matrix *matrix_create(int rows, int cols) {
    struct Matrix *m = calloc(1, sizeof *m);
    if (m == NULL) {
        return NULL;
    }
    m->rows = rows;
    m->cols = cols;
    m->data = calloc((size_t)rows, sizeof *m->data);
    if (m->data == NULL) {
        matrix_destroy(m);
        return NULL;
    }
    for (int r = 0; r < rows; r++) {
        m->data[r] = calloc((size_t)cols, sizeof *m->data[r]);
        if (m->data[r] == NULL) {
            matrix_destroy(m);
            return NULL;
        }
    }
    return m;
}

int main(void) {
    int rows, cols;
    scanf("%d %d", &rows, &cols);
    struct Matrix *m = matrix_create(rows, cols);
    if (m == NULL) {
        return 1;
    }
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            scanf("%d", &m->data[r][c]);
        }
    }
    for (int r = 0; r < rows; r++) {
        long long sum = 0;
        for (int c = 0; c < cols; c++) {
            sum += m->data[r][c];
        }
        printf(r + 1 < rows ? "%lld " : "%lld\n", sum);
    }
    for (int c = 0; c < cols; c++) {
        long long sum = 0;
        for (int r = 0; r < rows; r++) {
            sum += m->data[r][c];
        }
        printf(c + 1 < cols ? "%lld " : "%lld\n", sum);
    }
    matrix_destroy(m);
    matrix_destroy(NULL);
    return 0;
}

