#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

struct Node *push_front(struct Node *head, int value) {
    struct Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return NULL;
    }
    node->value = value;
    node->next = head;
    return node;
}

void free_list(struct Node *head) {
    while (head != NULL) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    struct Node *head = NULL;
    int x;
    while (scanf("%d", &x) == 1) {
        struct Node *bigger = push_front(head, x);
        if (bigger == NULL) {
            free_list(head);
            return 1;
        }
        head = bigger;
    }
    int count = 0;
    for (struct Node *n = head; n != NULL; n = n->next) {
        printf("%d ", n->value);
        count++;
    }
    printf("(%d)\n", count);
    free_list(head);
    return 0;
}

