#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char *line = malloc(256);
    if (line == NULL || fgets(line, 256, stdin) == NULL) {
        free(line);
        return 1;
    }
    line[strcspn(line, "\n")] = '\0';
    char *words[50];
    int count = 0;
    char *p = line;
    while (*p != '\0' && count < 50) {
        words[count++] = p;
        char *space = strchr(p, ' ');
        if (space == NULL) {
            break;
        }
        *space = '\0';
        p = space + 1;
    }
    for (int i = count - 1; i >= 0; i--) {
        printf(i > 0 ? "%s " : "%s\n", words[i]);
    }
    for (int i = 0; i < count; i++) {
        free(words[i]);
    }
    return 0;
}

