#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Stack {
    char **items;
    int count, capacity;
};

int stack_push(struct Stack *s, const char *word) {
    if (s->count == s->capacity) {
        int capacity = s->capacity ? s->capacity * 2 : 4;
        char **bigger = realloc(s->items, (size_t)capacity * sizeof *bigger);
        if (bigger == NULL) {
            return -1;
        }
        s->items = bigger;
        s->capacity = capacity;
    }
    size_t len = strlen(word);
    char *copy = malloc(len + 1);
    if (copy == NULL) {
        return -1;
    }
    memcpy(copy, word, len + 1);
    s->items[s->count++] = copy;
    return 0;
}

char *stack_pop(struct Stack *s) {
    if (s->count == 0) {
        return NULL;
    }
    return s->items[--s->count];
}

void stack_destroy(struct Stack *s) {
    for (int i = 0; i < s->count; i++) {
        free(s->items[i]);
    }
    free(s->items);
    s->items = NULL;
    s->count = 0;
    s->capacity = 0;
}

int main(void) {
    struct Stack s = {NULL, 0, 0};
    char command[8];
    while (scanf("%7s", command) == 1) {
        if (strcmp(command, "push") == 0) {
            char word[32];
            scanf("%31s", word);
            if (stack_push(&s, word) != 0) {
                break;
            }
        } else if (strcmp(command, "pop") == 0) {
            char *top = stack_pop(&s);
            if (top == NULL) {
                printf("empty\n");
            } else {
                printf("%s\n", top);
                free(top);
            }
        }
    }
    printf("left %d\n", s.count);
    stack_destroy(&s);
    return 0;
}

