#include <stdio.h>
#include <stdlib.h>

static int frees = 0;

void release(int **p) {
    if (*p != NULL) {
        free(*p);
        frees++;
        *p = NULL;
    }
}

int main(void) {
    int *a = malloc(sizeof *a);
    int *b = NULL;
    release(&a);
    release(&a);
    release(&b);
    printf("%d %d\n", frees, a == NULL);
    return 0;
}
